import sys; sys.path.insert(0,__import__('os').path.dirname(__import__('os').path.abspath(__file__)))
from qa_lib import *
import shutil; shutil.rmtree('/tmp/qa_prof_foret', ignore_errors=True)
q=QA('foret-complet', profile='/tmp/qa_prof_foret'); q.load()
J=q.js
J('nouvelle partie Aube',"T.newGame()","play")
# état fin d'acte I fabriqué (déjà couvert par qa_aube_full), puis VRAI voyage par Calixte
J('prépa fin acte I',"""(()=>{const L=__lumen,s=L.st;s.flags.acte1_fini=1;s.flags.boss_colosse=1;s.flags.lens_set=1;
  ['q_reveil','q_lentille','q_phare'].forEach(k=>s.quests[k]={state:'done',step:9,base:{}});L.give('epee_aube',1);L.G.equip('epee_aube',true);L.give('marteau',1);s.player.lvl=6;s.player.ecus=300;window.__old=1;return 'ok'})()""")
J('Calixte → Forêt',"T.talkTo('calixte',()=>0)")
q.reloaded()
J('arrivée Forêt',"T.info()+' '+T.q('q_verre')","active:parler")
J('Ambre 1',"T.talkTo('ambre')")
J('ponts ouverts',"JSON.stringify({vitres:__lumen.G.isGateOpen('b_vitres'),lis:__lumen.G.isGateOpen('b_lisiere'),q:T.q('q_verre')})")
for n in ['opaline','silex','galet']:
    J('boutique '+n,f"T.shopBuy('{n}')")
for n in ['silex','perle','ficus','tessel','galet','opaline','mousse']:
    J('dialogue '+n,f"(async()=>{{__lumen.G.screens.close();return await T.talkTo('{n}')}})()")
J('énigmes f1..f3',"""(async()=>{const L=__lumen,o=[];for(const [z,g] of [['f1','fg1'],['f2','fg2'],['f3','fg3']]){L.tpZone(z);await T.tick(300);o.push(g+':'+T.solve(g));}return o.join(' ')+' '+T.q('q_verre')})()""","active:lisiere")
J('belvédère + warp',"(async()=>{const L=__lumen;L.tpZone('belv');await T.tick(600);return L.G.zoneId()+' '+JSON.stringify(L.st.world.warps)})()")
J('lisière: ennemis',"(async()=>{const L=__lumen;L.tpZone('lisiere',[15,3]);await T.tick(1000);const t={};L.combat.enemies.forEach(e=>t[e.type]=(t[e.type]||0)+1);return JSON.stringify(t)+' '+T.q('q_verre')})()","active:temple")
J('lisière: combats (éclat de verre)',"(async()=>{const L=__lumen;const k=await T.cutAndKill(['eclat'],20000);return k+' eclats='+(L.st.inv.eclat_verre||0)+' givre='+(L.st.inv.givre_foret||0)})()")
J('lisière: coffres',"""(async()=>{const L=__lumen,o=[];for(const id of ['ch_lis_coeur','ch_lis_bague','ch_lis_ecus']){o.push(id+':'+await T.openChest(id));}return o.join(' ')})()""")
J('lisière: haie de ronces',"""(async()=>{const L=__lumen;const zi=L.G.zones.findIndex(z=>z.id==='lisiere');let c=0,n=0;for(let y=0;y<L.isl.h;y++)for(let x=0;x<L.isl.w;x++)if(L.isl.terrain[y][x]==='r'&&L.isl.zoneAt[y][x]===zi){n++;L.P.x=x*2;L.P.z=y*2-1.2;L.P.face=0;L.st.player.hp=999;for(let i=0;i<6&&L.isl.terrain[y][x]==='r';i++){L.combat.melee({mult:1});await T.tick(60);}if(L.isl.terrain[y][x]!=='r')c++;}return c+'/'+n})()""")
J('lisière: roches (marteau)',"""(async()=>{const L=__lumen;const zi=L.G.zones.findIndex(z=>z.id==='lisiere');L.G.equip('marteau',true);let n=0;for(let y=0;y<L.isl.h;y++)for(let x=0;x<L.isl.w;x++)if(L.isl.terrain[y][x]==='c'&&L.isl.zoneAt[y][x]===zi){L.P.x=x*2;L.P.z=y*2-1.3;L.P.face=0;L.st.player.hp=999;for(let i=0;i<8&&L.isl.terrain[y][x]==='c';i++){L.combat.melee({mult:1});await T.tick(150);}n++;}L.G.equip('epee_aube',true);return 'blocs '+n+' broken='+Object.keys(L.st.world.broken).length})()""")
J('temple: entrée',"(async()=>{const L=__lumen;L.tpZone('temple');await T.tick(1200);return T.q('q_verre')+' '+JSON.stringify(L.st.player.respawn)})()")
J('temple: salle combat',"(async()=>{const L=__lumen;L.tpZone('temple',[5,5]);await T.tick(1200);const k=await T.cutAndKill(e=>e.room==='td_combat',60000);await T.tick(1500);return k+' gate='+L.G.isGateOpen('td_combat')})()","gate=true")
J('temple: énigme',"(async()=>{const L=__lumen;L.tpZone('temple',[24,5]);await T.tick(300);return T.solve('td_light')})()")
J('temple: sentinelle clé',"(async()=>{const L=__lumen;L.tpZone('temple',[5,14]);await T.tick(1000);return await T.cutAndKill(['sentinelle'],60000)})()")
J('temple: coffre clé',"T.openChest('ch_cle_t')","ouvert:true")
J('temple: coffre épée',"T.openChest('ch_tresor_t')","ouvert:true")
J('temple: porte',"""(async()=>{const L=__lumen;const [x,y]=L.isl.gates.td_key.cells[0];return await T.useTarget('lock',x*2,(y-1)*2-0.4)+' ouverte='+L.G.isGateOpen('td_key')})()""","ouverte=true")
J('temple: roches cachées',"""(async()=>{const L=__lumen;const zi=L.G.zones.findIndex(z=>z.id==='temple');L.G.equip('marteau',true);let n=0;L.tpZone('temple',[4,19]);await T.tick(600);for(let y=0;y<L.isl.h;y++)for(let x=0;x<L.isl.w;x++)if(L.isl.terrain[y][x]==='c'&&L.isl.zoneAt[y][x]===zi){L.P.x=x*2;L.P.z=y*2-1.3;L.P.face=0;L.st.player.hp=999;for(let i=0;i<8&&L.isl.terrain[y][x]==='c';i++){L.combat.melee({mult:1});await T.tick(150);}n++;break;}L.G.equip('epee_aube',true);return n+' broken='+Object.keys(L.st.world.broken).length})()""")
J('temple: coffres cachés',"""(async()=>{const o=[];for(const id of ['ch_cache_t','ch_cache2_t'])o.push(id+':'+await T.openChest(id));return o.join(' ')})()""")
J('temple: boss',"(async()=>{const L=__lumen;L.tpZone('temple',[15,15]);await T.tick(1200);return await T.fightBoss(120000)})()","\"dead\":true")
