J('temple: suites',"JSON.stringify({flag:__lumen.st.flags.boss_verre,q:T.q('q_verre'),warp:__lumen.st.world.warps.temple,mode:__lumen.S.mode})")
J('temple: coffre prisme',"T.openChest('ch_prisme')","ouvert:true")
